-col-index[data-v-117e7417]{color:rgba(255,255,255,0.2);font-variant-numeric:tabular-nums;font-size:11px;letter-spacing:0.03em}.credits-col-avatar[data-v-117e7417]{width:32px;height:32px;border-radius:50%;object-fit:cover;background:rgba(255,255,255,0.06);display:block}.credits-avatar-fallback[data-v-117e7417]{display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:500;color:rgba(255,255,255,0.3);text-transform:uppercase}.credits-col-name[data-v-117e7417]{color:rgba(255,255,255,0.8);font-size:13px;font-weight:400;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-left:8px}.credits-empty[data-v-117e7417]{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);color:rgba(255,255,255,0.25);font-size:12px;letter-spacing:0.15em;text-transform:uppercase}.credits-footer[data-v-117e7417]{flex-shrink:0;padding:6px 14px;border-top:1px solid rgba(77,201,246,0.1);background:rgba(5,8,16,0.6);font-size:11px;color:rgba(255,255,255,0.25);text-align:center}
`, "",{"version":3,"sources":["webpack://./src/潮汐预设脚本/CreditsView.vue"],"names":[],"mappings":"AAiOA,+BACE,YAAa,CACb,qBAAsB,CACtB,WAAY,CACZ,YAAa,CACb,4BACF,CAGA,iCACE,aAAc,CACd,iBAAkB,CAClB,6CAAiD,CACjD,2BACF,CAEA,mCACE,mBAAoB,CACpB,kBAAmB,CACnB,OAAQ,CACR,gBAAiB,CACjB,iBAAkB,CAClB,qCAAyC,CACzC,gCAAoC,CACpC,0BAA8B,CAC9B,cAAe,CACf,cAAe,CACf,kBAAmB,CACnB,oBACF,CACA,yCACE,gCAAoC,CACpC,iCACF,CAEA,sCACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,gCACE,cAAe,CACf,eAAgB,CAChB,2BAA+B,CAC/B,oBACF,CAEA,iCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,cACF,CACA,uCACE,4BAAgC,CAChC,cAAe,CACf,wBAAyB,CACzB,oBACF,CACA,sCACE,2BAA+B,CAC/B,eACF,CAEA,+BACE,YAAa,CACb,QAAS,CACT,cAAe,CACf,2BACF,CACA,oCACE,YAAa,CACb,kBAAmB,CACnB,OACF,CACA,qCACE,2BAA+B,CAC/B,cAAe,CACf,wBAAyB,CACzB,oBACF,CAGA,qCACE,aAAc,CACd,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,gBAAiB,CACjB,4CAAgD,CAChD,2BACF,CACA,sCACE,aAAc,CACd,2BACF,CACA,uCACE,MAAO,CACP,sBAAuB,CACvB,WAAY,CACZ,YAAa,CACb,4BAAgC,CAChC,cAAe,CACf,aAAc,CACd,WACF,CACA,oDACE,2BACF,CACA,uCACE,UAAW,CACX,WAAY,CACZ,WAAY,CACZ,sBAAuB,CACvB,4BAAgC,CAChC,cAAe,CACf,cAAe,CACf,aAAc,CACd,SAAU,CACV,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,aACF,CACA,6CACE,2BACF,CAGA,iCACE,MAAO,CACP,YAAa,CACb,qBAAsB,CACtB,kBAAmB,CACnB,sBAAuB,CACvB,QAAS,CACT,2BAA+B,CAC/B,cACF,CACA,gCACE,2BACF,CACA,0CACE,UAAW,CACX,WAAY,CACZ,sCAA0C,CAC1C,qCAAyC,CACzC,iBAAkB,CAClB,oDACF,CACA,iCACE,GAAK,wBAA2B,CAClC,CACA,oCACE,gBAAiB,CACjB,iBAAkB,CAClB,sCAA0C,CAC1C,gCAAoC,CACpC,0BAA8B,CAC9B,cAAe,CACf,cAAe,CACf,oBACF,CACA,0CACE,gCACF,CAGA,mCACE,MAAO,CACP,eAAgB,CAChB,iBAAkB,CAClB,YAAa,CACb,oBAAqB,CACrB,iDACF,CACA,sDACE,SACF,CACA,4DACE,sBACF,CACA,4DACE,+BAAmC,CACnC,iBACF,CAEA,gCACE,iBAAkB,CAClB,KAAM,CACN,MAAO,CACP,SAAU,CACV,SAAU,CACV,mBACF,CAEA,kCACE,iBAAkB,CAClB,KAAM,CACN,MAAO,CACP,UAAW,CACX,cACF,CAEA,mCACE,WAAY,CACZ,YAAa,CACb,mCAAoC,CACpC,kBAAmB,CACnB,8CAAkD,CAClD,KAAM,CACN,2BACF,CACA,yCACE,gCACF,CAEA,oCACE,2BAA+B,CAC/B,iCAAkC,CAClC,cAAe,CACf,qBACF,CAEA,qCACE,UAAW,CACX,WAAY,CACZ,iBAAkB,CAClB,gBAAiB,CACjB,iCAAqC,CACrC,aACF,CAEA,0CACE,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,cAAe,CACf,eAAgB,CAChB,2BAA+B,CAC/B,wBACF,CAEA,mCACE,2BAA+B,CAC/B,cAAe,CACf,eAAgB,CAChB,kBAAmB,CACnB,eAAgB,CAChB,sBAAuB,CACvB,gBACF,CAEA,gCACE,iBAAkB,CAClB,OAAQ,CACR,QAAS,CACT,8BAAgC,CAChC,4BAAgC,CAChC,cAAe,CACf,qBAAsB,CACtB,wBACF,CAGA,iCACE,aAAc,CACd,gBAAiB,CACjB,yCAA6C,CAC7C,2BAA+B,CAC/B,cAAe,CACf,4BAAgC,CAChC,iBACF","sourcesContent":["<template>\n  <div class=\"credits-root\">\n    <!-- 顶部信息 -->\n    <div class=\"credits-header\">\n      <button class=\"credits-back-btn\" @click=\"$emit('back')\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n          <polyline points=\"15 18 9 12 15 6\" />\n        </svg>\n        返回\n      </button>\n      <div class=\"credits-header-info\">\n        <div class=\"credits-title\">感谢每一位点赞的朋友 👍</div>\n        <div class=\"credits-author\">\n          <span class=\"credits-author-label\">作者</span>\n          <span class=\"credits-author-name\">shiyue67</span>\n        </div>\n        <div class=\"credits-meta\" v-if=\"metadata\">\n          <span class=\"credits-meta-item\">\n            <span class=\"credits-meta-label\">总人数</span>\n            {{ metadata.total_users.toLocaleString() }}\n          </span>\n          <span class=\"credits-meta-item\">\n            <span class=\"credits-meta-label\">统计时间</span>\n            {{ formatTime(metadata.scraped_at) }}\n          </span>\n        </div>\n      </div>\n    </div>\n\n    <!-- 搜索框 -->\n    <div class=\"credits-search-bar\">\n      <svg class=\"credits-search-icon\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n        <circle cx=\"11\" cy=\"11\" r=\"8\" /><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\" />\n      </svg>\n      <input\n        class=\"credits-search-input\"\n        v-model=\"localSearch\"\n        placeholder=\"搜索用户名…\"\n        spellcheck=\"false\"\n      />\n      <button v-if=\"localSearch\" class=\"credits-search-clear\" @click=\"localSearch = ''\">×</button>\n    </div>\n\n    <!-- 加载 / 错误状态 -->\n    <div v-if=\"loading\" class=\"credits-status\">\n      <div class=\"credits-loading-spinner\" />\n      <span>加载中…</span>\n    </div>\n    <div v-else-if=\"error\" class=\"credits-status credits-error\">\n      <span>{{ error }}</span>\n      <button class=\"credits-retry-btn\" @click=\"loadData\">重试</button>\n    </div>\n\n    <!-- 虚拟滚动列表 -->\n    <div\n      v-else\n      ref=\"viewportRef\"\n      class=\"credits-viewport\"\n      @scroll=\"onScroll\"\n    >\n      <div class=\"credits-ghost\" :style=\"{ height: ghostHeight + 'px' }\" />\n      <div class=\"credits-content\" :style=\"{ transform: `translateY(${contentOffset}px)` }\">\n        <div\n          v-for=\"(user, i) in visibleUsers\"\n          :key=\"startIndex + i\"\n          class=\"credits-user-row\"\n        >\n          <div class=\"credits-col-index\">{{ String(startIndex + i + 1).padStart(3, '0') }}</div>\n          <img\n            v-if=\"user.avatar_url\"\n            class=\"credits-col-avatar\"\n            :src=\"user.avatar_url + '?size=64'\"\n            loading=\"lazy\"\n            alt=\"\"\n          />\n          <div v-else class=\"credits-col-avatar credits-avatar-fallback\">\n            {{ getInitial(user) }}\n          </div>\n          <div class=\"credits-col-name\">{{ user.global_name || user.username || 'Unknown' }}</div>\n        </div>\n      </div>\n\n      <!-- 空结果 -->\n      <div v-if=\"filteredData.length === 0 && !loading\" class=\"credits-empty\">\n        {{ rawData.length === 0 ? '暂无数据' : '无匹配结果' }}\n      </div>\n    </div>\n\n    <!-- 底部统计 -->\n    <div v-if=\"!loading && !error\" class=\"credits-footer\">\n      显示 {{ filteredData.length }} / {{ rawData.length }} 位用户\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nconst ITEM_HEIGHT = 56;\nconst BUFFER_ITEMS = 10;\n\n// CDN 地址 - 使用 reactions 版本号标签\nconst REACTIONS_URL = 'https://testingcf.jsdelivr.net/gh/sanmingyue/tavern_dist@reactions-v1.0.0/dist/reactions/reactions.json';\n\ninterface UserData {\n  id: string;\n  username: string;\n  global_name: string | null;\n  avatar_url: string | null;\n}\n\ninterface Metadata {\n  scraped_at: string;\n  channel_id: string;\n  message_id: string;\n  emoji: string;\n  total_users: number;\n}\n\ndefineEmits<{\n  back: [];\n}>();\n\nconst loading = ref(true);\nconst error = ref('');\nconst rawData = ref<UserData[]>([]);\nconst metadata = ref<Metadata | null>(null);\nconst localSearch = ref('');\nconst viewportRef = ref<HTMLDivElement | null>(null);\n\n// 过滤数据\nconst filteredData = computed(() => {\n  const term = localSearch.value.trim().toLowerCase();\n  if (!term) return rawData.value;\n  return rawData.value.filter(user => {\n    const globalName = (user.global_name || '').toLowerCase();\n    const username = (user.username || '').toLowerCase();\n    return globalName.includes(term) || username.includes(term);\n  });\n});\n\n// 虚拟滚动\nconst scrollTop = ref(0);\nconst viewportHeight = ref(400);\n\nconst ghostHeight = computed(() => filteredData.value.length * ITEM_HEIGHT);\n\nconst startIndex = computed(() => {\n  const raw = Math.floor(scrollTop.value / ITEM_HEIGHT);\n  return Math.max(0, raw - BUFFER_ITEMS);\n});\n\nconst endIndex = computed(() => {\n  const raw = Math.ceil((scrollTop.value + viewportHeight.value) / ITEM_HEIGHT);\n  return Math.min(filteredData.value.length - 1, raw + BUFFER_ITEMS);\n});\n\nconst contentOffset = computed(() => startIndex.value * ITEM_HEIGHT);\n\nconst visibleUsers = computed(() => {\n  if (filteredData.value.length === 0) return [];\n  return filteredData.value.slice(startIndex.value, endIndex.value + 1);\n});\n\nfunction onScroll() {\n  if (!viewportRef.value) return;\n  scrollTop.value = viewportRef.value.scrollTop;\n  viewportHeight.value = viewportRef.value.clientHeight;\n}\n\n// 搜索变化时重置滚动\nwatch(localSearch, () => {\n  if (viewportRef.value) {\n    viewportRef.value.scrollTop = 0;\n    scrollTop.value = 0;\n  }\n});\n\n// 格式化时间\nfunction formatTime(isoString: string): string {\n  if (!isoString) return '未知';\n  const d = new Date(isoString);\n  return `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;\n}\n\n// 获取首字母\nfunction getInitial(user: UserData): string {\n  const name = user.global_name || user.username || '?';\n  return name.charAt(0).toUpperCase();\n}\n\n// 加载数据\nasync function loadData() {\n  loading.value = true;\n  error.value = '';\n  try {\n    const resp = await fetch(REACTIONS_URL);\n    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);\n    const json = await resp.json();\n\n    if (json.data && Array.isArray(json.data)) {\n      rawData.value = json.data;\n      metadata.value = json.metadata || null;\n    } else if (Array.isArray(json)) {\n      rawData.value = json;\n    } else {\n      throw new Error('数据格式错误');\n    }\n  } catch (e: any) {\n    error.value = `加载失败: ${e.message || e}`;\n    console.error('[致谢页面] 数据加载失败:', e);\n  } finally {\n    loading.value = false;\n  }\n}\n\nonMounted(() => {\n  loadData();\n  nextTick(() => {\n    if (viewportRef.value) {\n      viewportHeight.value = viewportRef.value.clientHeight;\n    }\n  });\n});\n</script>\n\n<style scoped>\n.credits-root {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  color: rgba(255, 255, 255, 0.88);\n}\n\n/* ═══ 顶部 ═══ */\n.credits-header {\n  flex-shrink: 0;\n  padding: 12px 14px;\n  border-bottom: 1px solid rgba(77, 201, 246, 0.15);\n  background: rgba(5, 8, 16, 0.6);\n}\n\n.credits-back-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 10px;\n  border-radius: 6px;\n  border: 1px solid rgba(77, 201, 246, 0.2);\n  background: rgba(77, 201, 246, 0.06);\n  color: rgba(77, 201, 246, 0.9);\n  font-size: 12px;\n  cursor: pointer;\n  margin-bottom: 10px;\n  transition: all 0.15s;\n}\n.credits-back-btn:hover {\n  background: rgba(77, 201, 246, 0.15);\n  border-color: rgba(77, 201, 246, 0.4);\n}\n\n.credits-header-info {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.credits-title {\n  font-size: 15px;\n  font-weight: 600;\n  color: rgba(77, 201, 246, 0.95);\n  letter-spacing: 0.5px;\n}\n\n.credits-author {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 13px;\n}\n.credits-author-label {\n  color: rgba(255, 255, 255, 0.35);\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n}\n.credits-author-name {\n  color: rgba(255, 255, 255, 0.8);\n  font-weight: 500;\n}\n\n.credits-meta {\n  display: flex;\n  gap: 18px;\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.5);\n}\n.credits-meta-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.credits-meta-label {\n  color: rgba(255, 255, 255, 0.3);\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n}\n\n/* ═══ 搜索框 ═══ */\n.credits-search-bar {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 14px;\n  border-bottom: 1px solid rgba(77, 201, 246, 0.1);\n  background: rgba(5, 8, 16, 0.4);\n}\n.credits-search-icon {\n  flex-shrink: 0;\n  color: rgba(255, 255, 255, 0.3);\n}\n.credits-search-input {\n  flex: 1;\n  background: transparent;\n  border: none;\n  outline: none;\n  color: rgba(255, 255, 255, 0.88);\n  font-size: 12px;\n  padding: 4px 0;\n  min-width: 0;\n}\n.credits-search-input::placeholder {\n  color: rgba(255, 255, 255, 0.2);\n}\n.credits-search-clear {\n  width: 18px;\n  height: 18px;\n  border: none;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.35);\n  cursor: pointer;\n  font-size: 14px;\n  line-height: 1;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n.credits-search-clear:hover {\n  color: rgba(255, 255, 255, 0.7);\n}\n\n/* ═══ 状态 ═══ */\n.credits-status {\n  flex: